import { Button, ToasterProvider, useToaster } from '@gravity-ui/uikit';

function CornerButton() {
  const { add } = useToaster();

  const showToast = () => {
    add({
      name: 'corner-toast',
      title: 'Уведомление',
      content: 'Кнопка нажата! Это сообщение скоро само исчезнет.',
      theme: 'success',
      autoClose: true,
      timeout: 3000,
    });
  };

  return (
    <div style={{ position: 'fixed', right: 24, bottom: 24 }}>
      <Button view="action" size="l" onClick={showToast}>
        Показать уведомление
      </Button>
    </div>
  );
}

export function App() {
  return (
    <ToasterProvider>
      <CornerButton />
    </ToasterProvider>
  );
}

